  "officialResources": {
    "title": "Official Transport Department & Customs Resources",
    "html": "<ul class=\"space-y-2 text-sm\">\n  <li><a href=\"https://www.td.gov.hk/en/public_services/licences_and_permits/vehicle_first_registration/index.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-primary font-semibold hover:underline\">Transport Department — First Registration of Vehicles</a> — Official Procedures &amp; Forms</li>\n  <li><a href=\"https://www.epd.gov.hk/epd/english/environmentinhk/air/prob_solutions/ev_one_for_one_replacement.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-primary font-semibold hover:underline\">Environmental Protection Department — EV One-for-One Scheme</a> — Eligibility Verification Portal</li>\n  <li><a href=\"https://www.customs.gov.hk/en/service-enforcement-information/trade-facilitation/motor-vehicles/index.html\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-primary font-semibold hover:underline\">Hong Kong Customs &amp; Excise — Motor Vehicles Valuation</a> — Taxable Value &amp; Initial Assessment</li>\n</ul>\n<p class=\"text-xs text-muted mt-3\">Keep all vehicle registration documents (TD59), scrap certificates, and Customs valuation notices for vehicle resale and audit purposes.</p>"
  },
